// Phase 1 verification: drive the subtitle-service /subtitles/transcribe
// route with a real WAV and assert timed segments come back from whisper.
//
// Usage: node tools/test-subtitle-transcribe.mjs <audioPath> [language]
// Defaults to a 3s 16kHz mono sine WAV generated by ffmpeg if none given.

import http from 'node:http';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const AUDIO_PATH = process.argv[2];
const LANGUAGE = process.argv[3] || 'en';
const SUBTITLE_URL = process.env.SUBTITLE_URL || 'http://127.0.0.1:8090';
const WHISPER_URL = process.env.WHISPER_URL || 'http://127.0.0.1:8000';

let audioPath = AUDIO_PATH;
if (!audioPath) {
  const tmp = path.join(os.tmpdir(), 'wideo11-test-audio.wav');
  execFileSync('ffmpeg', [
    '-y', '-f', 'lavfi',
    '-i', 'sine=frequency=300:duration=3',
    '-ar', '16000', '-ac', '1', '-c:a', 'pcm_s16le', tmp,
  ], { stdio: 'ignore' });
  audioPath = tmp;
}

const audio = fs.readFileSync(audioPath);
const boundary = '----WebKitFormBoundary7MA4YWxkTrZu0gW';

function multipart(field, filename, data, type) {
  let s = `--${boundary}\r\n`;
  s += `Content-Disposition: form-data; name="${field}"; filename="${filename}"\r\n`;
  s += `Content-Type: ${type}\r\n\r\n`;
  return Buffer.concat([Buffer.from(s, 'binary'), data, Buffer.from('\r\n', 'binary')]);
}

const body = Buffer.concat([
  multipart('audio', path.basename(audioPath), audio, 'audio/wav'),
  multipart('language', '', Buffer.from(LANGUAGE, 'binary'), 'text/plain'),
  Buffer.from(`--${boundary}--\r\n`, 'binary'),
]);

function post(url, data, contentType) {
  return new Promise((resolve, reject) => {
    const u = new URL(url);
    const req = http.request({
      hostname: u.hostname, port: u.port, path: u.pathname + u.search,
      method: 'POST', headers: { 'Content-Type': contentType, 'Content-Length': data.length },
    }, res => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => resolve({ status: res.statusCode, body: d }));
    });
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

function get(url) {
  return new Promise((resolve, reject) => {
    const u = new URL(url);
    const req = http.request({ hostname: u.hostname, port: u.port, path: u.pathname + u.search, method: 'GET' }, res => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => resolve({ status: res.statusCode, body: d }));
    });
    req.on('error', reject);
    req.end();
  });
}

async function probe(url) {
  try {
    return await get(url);
  } catch (e) {
    return { status: 0, body: String(e).slice(0, 120) };
  }
}

async function main() {
  const checks = [];
  const t0 = Date.now();

  // 1. subtitle-service process alive
  const root = await get(`${SUBTITLE_URL}/health`);
  checks.push({ name: 'subtitle-service /health', ok: root.status === 200, detail: `${root.status} ${root.body.slice(0, 80)}` });

  // 2. whisper reachable through subtitle-service
  const tHealth = await get(`${SUBTITLE_URL}/subtitles/transcribe/health`);
  checks.push({ name: 'transcribe/health (whisper reachable)', ok: tHealth.status === 200, detail: tHealth.body.slice(0, 120) });

  // 3. whisper directly
  const wHealth = await get(`${WHISPER_URL}/health`);
  checks.push({ name: 'whisper /health direct', ok: wHealth.status === 200, detail: wHealth.body.slice(0, 80) });

  // 4. REAL transcription: send the WAV, expect segments back
  const t0b = Date.now();
  const transcribe = await post(`${SUBTITLE_URL}/subtitles/transcribe`, body,
    `multipart/form-data; boundary=${boundary}`);
  const elapsed = ((Date.now() - t0b) / 1000).toFixed(1);
  let parsed = null;
  try { parsed = JSON.parse(transcribe.body); } catch { /* not json */ }
  const hasSegments = parsed && Array.isArray(parsed.segments);
  const segmentCount = hasSegments ? parsed.segments.length : 0;
  checks.push({
    name: 'POST /subtitles/transcribe returns segments',
    ok: transcribe.status === 200 && hasSegments,
    detail: `HTTP ${transcribe.status} ${elapsed}s segments=${segmentCount} lang=${parsed?.language ?? '?'} first=${JSON.stringify(parsed?.segments?.[0] ?? {}).slice(0, 120)}`,
  });

  // 5. whisper not reachable -> 503 (feature off), not a fake success
  //    (can't easily simulate without stopping whisper; assert the error path
  //     exists in code instead — see service.go ErrWhisperUnavailable)

  const allPass = checks.every(c => c.ok);
  console.log(`\n=== Phase 1: AURA auto-subtitles end-to-end (${((Date.now() - t0) / 1000).toFixed(1)}s) ===`);
  for (const c of checks) {
    console.log(`${c.ok ? 'PASS' : 'FAIL'}  ${c.name}`);
    console.log(`       ${c.detail}`);
  }
  console.log(allPass ? '\nRESULT: PASS' : '\nRESULT: FAIL');
  process.exit(allPass ? 0 : 1);
}

main().catch(e => { console.error(e); process.exit(2); });